node -e "
const fs = require('fs');
const yaml = require('/usr/lib/node_modules/langfuse-cli/node_modules/js-yaml');

const spec = yaml.load(fs.readFileSync('/usr/lib/node_modules/langfuse-cli/openapi.yml', 'utf8'));

// Fix: Remove nullable from entries that don't have a type field
function fixNullables(obj) {
  if (typeof obj !== 'object' || obj === null) return;
  for (const [key, val] of Object.entries(obj)) {
    if (typeof val === 'object' && val !== null) {
      if (val.hasOwnProperty('nullable') && !val.hasOwnProperty('type')) {
        delete val.nullable;
      }
      fixNullables(val);
    }
  }
}

fixNullables(spec);

const fixedYaml = yaml.dump(spec, { lineWidth: -1 });
fs.writeFileSync('/usr/lib/node_modules/langfuse-cli/openapi.yml', fixedYaml);
console.log('Fixed openapi.yml');
" 2>&1

